ui.css:
.panel { border: 24px solid transparent; border-image: url(ornament.svg) 26 fill / 24px stretch; color: #efe9dc; font: 400 34px/1.05 'Limelight', Georgia, serif; letter-spacing: .06em; text-shadow: 2px 3px 0 #000; filter: drop-shadow(0 5px 0 rgba(10,8,6,.32)); }
.panel small { font: 400 12px/1.2 'Special Elite', monospace; letter-spacing: .28em; color: #b9b1a1; }
.bar { position: relative; width: 252px; height: 26px; border: 2px solid #efe9dc; border-radius: 13px; background: #17130f; box-shadow: 0 0 0 3px #17130f, 0 5px 0 3px rgba(10,8,6,.32); overflow: hidden; }
.bar > i { position: absolute; inset: 0 auto 0 0; border-radius: 11px; background: linear-gradient(180deg, rgba(255,255,255,.45) 0 22%, rgba(255,255,255,0) 22% 70%, rgba(23,19,15,.18) 70%), repeating-linear-gradient(-45deg, #efe9dc 0 4px, #c9c1b1 4px 6px); }
.filmstrip { height: 26px; background: #17130f; position: relative; }
.filmstrip::after { content: ''; position: absolute; inset: 0; background: repeating-linear-gradient(90deg, transparent 0 6px, #e9e2d2 6px 12px, transparent 12px 20px) left 0 top 3px / 100% 4px no-repeat, repeating-linear-gradient(90deg, transparent 0 6px, #e9e2d2 6px 12px, transparent 12px 20px) left 0 bottom 3px / 100% 4px no-repeat; }
